# -*- coding: utf-8 -*-
"""ch03 R2 ops 4: 3.3.4尾段+3.4+判例+四步法+术语速查 (行376-551)"""

OPS = [
(391, 391, "五个样本拼出",
 "五个样本拼出省级修编的完整生态位：**江苏市政定额示范“怎么调量”**（按册按章下调人工机械消耗、重定费率与取费基数）；**江苏消耗量定额征求意见稿示范“怎么改名与问询”**（计价表改消耗量定额、公开征求意见到日到点）；**甘肃工业厂房定额示范“为什么立新项”**（落实38号改革方案、动态化管理、服务产业需求）；**江苏智能建造补充定额示范“新技术怎么进定额”**；**陕西2025新版资料示范“发布物有哪些”**（消耗量定额、基价表、台班费用定额、费用规则四件套成套发布）（P000325、P000329、P000315、P000330、P000326）。修编成果最终落回三阶段流程与水平测算——交底资料里“人工下调10%”之类的表述，背后正是新旧定额水平对比测算的结论（P000356、P000325）。"),
(400, 400, "在实际工程建设",
 "实际工程建设与养护里，现场常遇非标准施工环境：高层建筑物超高、施工与生产同时进行、有害身体健康的环境、场地狭窄逼出材料二次转运、通车路段交通干扰、小批量零星工程（P000303、P000310、P000316）。这些条件带来施工人员与机械的大幅降效、材料运输损耗的显著增加。造价人与商务口负责人必须吃透规范与定额里的动态调整机制，精准核算机料消耗与增加费用（P000303、P000319）。"),
(429, 429, "  1. **超高增加费裁定**",
 "  1. **超高增加费裁定**：依定额0.3.5条，必须按建筑面积加权平均降效系数 \\(J_{\\text{平均}}\\) 计算，且按裙楼、塔楼分栋分别计算，仅乘入室外地坪以上全部可计量分部分项工程与措施项目（不含预制构件制作及运输、钢结构构件制作等场外制作项目）的人工费与机械费（P000303）；按公式核定结果显著低于施工单位按最高楼层系数整体申报的口径，多报费用被核减（P000303）。"),
(430, 430, "  2. **施工干扰降效裁定**",
 "  2. **施工干扰降效裁定**：依定额0.1.12条，仅“施工与生产同时进行使施工受到干扰”的特定区域可按人工费乘以1.10系数；查施工日志，只有裙楼续建区域与共享中庭区域受人员出入干扰，塔楼有独立施工电梯与通道未受影响——故仅对实际受扰区域的分部分项工程人工费乘以1.10系数，塔楼不予加算（P000303）。"),
(431, 431, "  3. **二次运输费裁定**",
 "  3. **二次运输费裁定**：依定额0.1.6条，因施工环境或场地条件限制致材料重复转运装卸的，应另计二次运输费；调取经审定的施工组织设计与现场堆场照片，证实确因临街无堆场在场外租房转运，裁定支持按实计列（P000303）。"),
(432, 432, "* **教训/启示**：应对复杂",
 "* **教训/启示**：应对复杂施工条件的动态调整与费用索赔，商务负责人与造价师要做到“规则精细、证据完整”：超高增加费严格执行加权平均系数公式，切忌套最高层系数（P000303）；干扰1.10系数只认实际受生产干扰的区域，并留存现场交接与干扰记录（P000303）；二次运输费索赔须备齐场地受限图纸、经审定的转运方案与现场签证，方能过审计合规关（P000303、P000319）。"),
(441, 441, "在套用预算定额",
 "套用预算定额或消耗量定额时，造价人员须对照施工图纸、设计说明与施工组织设计，对分项工程的名称、工程内容、技术特征、施工方法及材料规格做“五对照”审查（P000319）。"),
(445, 445, "* **【关键数字与套用计算示例】**",
 "* **【关键数字与套用计算示例】**：以 M10.0 水泥砂浆砌筑烧结普通砖砖基础 200m³ 工程为例，查建筑工程预算定额，烧结普通砖砖基础的定额子目编号为 3-15（P000319）。核对图纸设计的砂浆强度（M10.0）、砖材质（烧结普通砖）及施工工序与 3-15 子目完全一致，即可直接套用（P000319）。定额表查得该子目定额基价 2754 元/10m³，该分项工程的定额直接工程费计算为："),
(454, 454, "定额换算通常遵循",
 "定额换算通常循“换药不换汤”：只调整允许换算的材料或机械单价与消耗量，人工工日及其他基础消耗量保持不变（P000305、P000319）。"),
(470, 470, "当遇有新技术",
 "遇新技术、新工艺、新结构或新材料（“四新”技术）导致国家、地方及行业定额完全缺项时，造价人员不得随意借用无关定额，必须编制补充定额（P000302、P000305）。"),
(473, 481, "1. **第一步：测定现场工效与基准消耗量**",
 "1. **第一步：测定现场工效与基准消耗量**\n   按3.1节测定标准在施工现场设试验区，用计时观察法测单位“四新”分项工程的人工工日（区分基本用工与幅度差）、材料净用量与现场损耗率、机械台班消耗量（P000302、P000311）。\n2. **第二步：编写补充定额项目说明与计算规则**\n   写清适用范围、工作内容（主要与次要工序）、计量单位（如 m³、㎡、t）与工程量计算规则，与现行计价规范保持一致（P000303、P000311）。\n3. **第三步：组合编制补充单位估价表与综合单价**\n   测定的工料机消耗量乘以项目所在地现行人工日工资单价、材料预算价格与机械台班单价得直接费基价，再按法定费率加算企业管理费与利润（P000311、P000320）。\n4. **第四步：完成法定备案与数字化平台上传**\n   * **住建领域备案**：依《房屋建筑与装饰工程消耗量定额》总说明，补充定额须随工程设计预算文件按规定报住建部或省市造价管理机构备案（P000302）。\n   * **公路领域数字化上传**：依《公路工程预算定额》（2018）总说明，补充定额随预算文件送审的同时**必须将数据上传“公路工程造价依据信息管理平台”**，纳入全国造价动态监管体系（P000305）；未完成上传与备案的，结算审计不予认可（P000305）。"),
(490, 490, "  1. **配合比换算纠纷裁判**",
 "  1. **配合比换算纠纷裁判**：依《公路工程预算定额》总说明第九条——实际施工配合比用量与定额配合比表用量不同时，除表说明允许者外均不得调整；配合比表水泥用量已综合考虑不同品种因素，不论采用何种水泥均不得调整定额用量（P000305）——施工单位擅自按实际配合比增加水泥用量属违法换算，**42万元水泥加算费用全额扣减**，严格按定额配合比表执行（P000305）。"),
(491, 491, "  2. **补充定额纠纷裁判**",
 "  2. **补充定额纠纷裁判**：依总说明第十六条，补充定额须按定额编制原则编制，且数据应上传“公路工程造价依据信息管理平台”（P000305）；施工单位自编补充定额既未经建设单位与造价监管部门审查、又未上传全国平台，属非法计价依据（P000305），审计拒绝按 180 元/㎡结算，改由造价监管部门会同发承包双方按现场技术测定数据重新核定，最终按 135 元/㎡核定结算，核减金额 65 万元。"),
(540, 551, "* **预算定额**",
 "* **预算定额**：正常施工条件下完成一定计量单位合格分项工程或结构构件所需人工、材料、施工机械台班数量标准及其货币表现，传统“量价合一”计价体系的核心依据 （P000312、P000320）。\n* **消耗量定额**：只界定完成合格分项工程所需人工工日、材料净用量及合理损耗、机械台班等物理“量”，不固化价格与管理费费率，“量价分离”与企业自主定价的基础 （P000304）。\n* **人工幅度差**：合理施工组织下因工种交接、工艺间歇、质量检查等无法按工序直接计入的工日损失，施工定额工效向预算定额工效转换的调整系数 （P000302、P000311）。\n* **机械幅度差**：机械正常施工中因场地转移、临时供电间歇、配合辅助机械等不可避免停歇降效增加的时间消耗 （P000302、P000315）。\n* **材料损耗率**：场内运输、施工操作及现场堆放不可避免损耗占材料净用量的百分比，公式为 \\\\(\\text{损耗率} = \\frac{\\text{损耗量}}{\\text{净用量}} \\times 100\\%\\\\) （P000302、P000303）。\n* **单位估价表**：以定额工料机消耗量乘特定地区现行人工日工资单价、材料预算价格、机械台班单价算出的分项工程直接费基价汇总表 （P000311）。\n* **加权平均超高降效系数（\\\\(J_{\\text{平均}}\\\\)）**：建筑物高度超8层或24米时，按各楼层建筑面积与对应高度区段降效系数加权算出的整栋建筑超高增加费调整系数 （P000303）。\n* **换算定额（H）**：设计材料规格、强度等级或施工方法与定额取定不符且规则允许换算时，调整原定额部分要素形成的子目，编号尾部注明“换”或“H” （P000319）。\n* **补充定额**：新技术、新工艺、新材料致现行定额完全缺项时，经现场实测与技术经济分析编制的临时计价依据，须依法备案并上传官方数据监管平台 （P000305、P000315）。\n* **秒表测时法**：现场以作业活动为对象，对作业要素周期性观测、用秒表记录时间消耗的方法，GB/T 23859—2025 两种现场测定法之一 （P000354）。\n* **影像记录法**：GB/T 23859—2025 新增测时方法，以可重现影像读取作业要素定时点时间，程序上须事先与作业人员沟通并取得同意 （P000354）。\n* **企业定额**：建筑企业按自身技术与管理水平编制、反映个别成本的内部定额，水平高于预算定额、低于施工定额，用于投标报价与成本控制 （P000321）。"),
]
